/**
 * Full tunnel configuration.
 */
public struct GotaTunConfig: Equatable, Hashable, Codable {
    /**
     * WireGuard private key (32 bytes).
     */
    public let privateKey: Data
    /**
     * Tunnel interface IPv4 address (e.g. "10.64.0.2").
     */
    public let ipv4Address: String
    /**
     * Tunnel interface IPv6 address.
     */
    public let ipv6Address: String
    /**
     * Tunnel MTU.
     */
    public let mtu: UInt16
    /**
     * Exit peer (always present).
     */
    public let exitPeer: GotaTunPeer
    /**
     * Entry peer for multihop, or `None` for singlehop.
     */
    public let entryPeer: GotaTunPeer?
    /**
     * Gateway IPv4 address used for connectivity pings (e.g. "10.64.0.1").
     */
    public let ipv4Gateway: String
    /**
     * How long to wait for the tunnel to establish connectivity (seconds).
     */
    public let establishTimeoutSecs: UInt32
    /**
     * Enable post-quantum key exchange.
     */
    public let enablePq: Bool
    /**
     * Enable DAITA.
     */
    public let enableDaita: Bool
    /**
     * Obfuscation method for the ingress relay.
     */
    public let obfuscation: GotaTunObfuscation

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * WireGuard private key (32 bytes).
         */privateKey: Data, 
        /**
         * Tunnel interface IPv4 address (e.g. "10.64.0.2").
         */ipv4Address: String, 
        /**
         * Tunnel interface IPv6 address.
         */ipv6Address: String, 
        /**
         * Tunnel MTU.
         */mtu: UInt16, 
        /**
         * Exit peer (always present).
         */exitPeer: GotaTunPeer, 
        /**
         * Entry peer for multihop, or `None` for singlehop.
         */entryPeer: GotaTunPeer?, 
        /**
         * Gateway IPv4 address used for connectivity pings (e.g. "10.64.0.1").
         */ipv4Gateway: String, 
        /**
         * How long to wait for the tunnel to establish connectivity (seconds).
         */establishTimeoutSecs: UInt32, 
        /**
         * Enable post-quantum key exchange.
         */enablePq: Bool, 
        /**
         * Enable DAITA.
         */enableDaita: Bool, 
        /**
         * Obfuscation method for the ingress relay.
         */obfuscation: GotaTunObfuscation) {
        self.privateKey = privateKey
        self.ipv4Address = ipv4Address
        self.ipv6Address = ipv6Address
        self.mtu = mtu
        self.exitPeer = exitPeer
        self.entryPeer = entryPeer
        self.ipv4Gateway = ipv4Gateway
        self.establishTimeoutSecs = establishTimeoutSecs
        self.enablePq = enablePq
        self.enableDaita = enableDaita
        self.obfuscation = obfuscation
    }

    

    
}

